package com.example.solarfarm.service;

import com.example.solarfarm.domain.*; import com.example.solarfarm.domain.Enums.PanelStatus; import com.example.solarfarm.repository.*; import com.example.solarfarm.common.Dtos; import org.springframework.stereotype.Service; import java.util.*;
@Service public class PanelService { private final PanelRepository repo; public PanelService(PanelRepository r){repo=r;} public List<Dtos.PanelResponse> all(PanelStatus status){return (status==null?repo.findAll():repo.findByStatus(status)).stream().map(this::map).toList();} public Panel find(String id){return repo.findByPanelId(id).orElseThrow(()->new NoSuchElementException("Panel "+id+" was not found"));} public Dtos.PanelResponse map(Panel p){return new Dtos.PanelResponse(p.getPanelId(),p.getRowIndex(),p.getColumnIndex(),p.getStringId(),p.getNominalPowerW(),p.getEfficiencyFactor(),p.getStatus().name());} public void update(Panel p,String severity,boolean anomaly){p.setStatus(!anomaly?PanelStatus.HEALTHY:("CRITICAL".equals(severity)?PanelStatus.FAULT:PanelStatus.WARNING));repo.save(p);} }
